import{_ as t,o,c as d,a5 as i}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Plan — Update Trend Flow (lean LLM-label pipeline)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/ai-features/update-trend-flow/plan.md","filePath":"feature/ai-features/update-trend-flow/plan.md"}'),a={name:"feature/ai-features/update-trend-flow/plan.md"};function c(l,e,n,r,s,p){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="plan-—-update-trend-flow-lean-llm-label-pipeline" tabindex="-1">Plan — Update Trend Flow (lean LLM-label pipeline) <a class="header-anchor" href="#plan-—-update-trend-flow-lean-llm-label-pipeline" aria-label="Permalink to &quot;Plan — Update Trend Flow (lean LLM-label pipeline)&quot;">​</a></h1><h2 id="_1-luong-moi" tabindex="-1">1. Luồng mới <a class="header-anchor" href="#_1-luong-moi" aria-label="Permalink to &quot;1. Luồng mới&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T0 Ingestion → T1 BotFilter → T2 LLM Label → T4 Burst → T5 Sentiment → T7 Fusion</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tầng</th><th>Nhiệm vụ</th><th>Output context</th></tr></thead><tbody><tr><td>T0</td><td>Nạp + dedup crawl</td><td><code>raw_items</code></td></tr><tr><td>T1</td><td>Lọc bot (KB1/2/3A/3B/5/6)</td><td>drop/blacklist/trend_signal</td></tr><tr><td>T2</td><td>Clean text → PhoBERT topic+emotion+NER → fallback Gemini</td><td><code>topics</code>, <code>emotions</code>, <code>emotion_dists</code>, <code>ner_entities</code>, <code>keyphrases</code></td></tr><tr><td>T4</td><td>Burst = density+velocity+coverage+engage</td><td><code>anomaly_scores</code>, <code>time_series</code></td></tr><tr><td>T5</td><td>Sentiment (dư luận) = comment emotion + reaction + share/like</td><td><code>moods</code>, <code>mood_stats</code></td></tr><tr><td>T7</td><td>Cluster keyphrase → CandidateTrend + nhãn + rank</td><td><code>final_candidates</code></td></tr></tbody></table><h2 id="_2-hai-lop-cam-xuc-tach-bach" tabindex="-1">2. Hai lớp cảm xúc (tách bạch) <a class="header-anchor" href="#_2-hai-lop-cam-xuc-tach-bach" aria-label="Permalink to &quot;2. Hai lớp cảm xúc (tách bạch)&quot;">​</a></h2><ul><li><code>ctx.emotions</code> (T2) = <strong>author sentiment</strong> — emotion trên text post (6 lớp).</li><li><code>ctx.emotion_dists</code> (T2) = softmax % 6 lớp từng post.</li><li><code>ctx.moods</code> (T5) = <strong>dư luận/user sentiment</strong> — emotion trên comment + reaction.</li></ul><p>T7 gộp: <code>emotion</code> (author, majority), <code>mood</code> (dư luận, majority), <code>emotion_dist</code> (trung bình softmax cluster), <code>brand_risk</code> = f(mood).</p><h2 id="_3-model" tabindex="-1">3. Model <a class="header-anchor" href="#_3-model" aria-label="Permalink to &quot;3. Model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nhánh</th><th>Demo (local dir)</th><th>Production (HF repo)</th></tr></thead><tbody><tr><td>Base</td><td><code>vinai/phobert-base-v2</code></td><td><code>vinai/phobert-base-v2</code></td></tr><tr><td>Emotion 6 lớp (v12)</td><td><code>khongpush_gihub_MCP/dataset_final/emotion_v12_adversarial_model</code></td><td><code>anha12/brandhub-phobert-V12-emotion</code></td></tr><tr><td>Topic 12 lớp (V5)</td><td><code>khongpush_gihub_MCP/dataset_final/topic_model</code></td><td><code>anha12/brandhub-phobert-V5-topic</code></td></tr><tr><td>NER 5 loại</td><td><code>khongpush_gihub_MCP/dataset_final/ner_model</code></td><td><code>anha12/brandhub-phobert-ner</code></td></tr></tbody></table><p>Gemini fallback: demo <code>LLM_API_KEY</code>/<code>LLM_MODEL</code> (urllib); production <code>settings.gemini_api_key</code>/<code>settings.gemini_model</code> (GeminiClient httpx).</p><h2 id="_4-files-cham" tabindex="-1">4. Files chạm <a class="header-anchor" href="#_4-files-cham" aria-label="Permalink to &quot;4. Files chạm&quot;">​</a></h2><p><strong>Production (<code>brandhub-ai-service</code>):</strong></p><ul><li><code>app/services/pipeline/llm_label.py</code> — <code>label_posts</code> return 5-tuple (thêm <code>emotion_probs</code>)</li><li><code>app/services/pipeline/phobert.py</code> — thêm <code>predict_emotion_probs</code> (softmax)</li><li><code>app/services/pipeline/steps/t2_nlp_step.py</code> — unpack 5, lưu <code>emotion_dists</code></li><li><code>app/services/pipeline/steps/t4_burst_step.py</code> — burst 4 signal</li><li><code>app/services/pipeline/steps/t5_sentiment_step.py</code> — dư luận</li><li><code>app/services/pipeline/steps/t7_fusion_step.py</code> — gộp <code>emotion_dist</code></li><li><code>app/services/pipeline/context.py</code> — thêm <code>emotions</code>, <code>emotion_dists</code>, <code>keyphrases</code></li><li><code>app/models/trend_models.py</code> — <code>CandidateTrend.emotion_dist</code></li><li><code>app/models/crawler_models.py</code> — <code>RawComment</code> + <code>raw_comment_objects</code></li><li><code>app/services/adapters/facebook_playwright_adapter.py</code> — giữ author+time comment</li><li><code>app/services/trend_service.py</code> — step list lean</li></ul><p><strong>Demo (<code>trend-pipeline</code>):</strong></p><ul><li><code>pipeline/{llm_label,model_inference,context,models}.py</code> + <code>pipeline/steps/t{2,4,5,7}_*.py</code> + <code>loader.py</code> + <code>run.py</code> + <code>ui.py</code></li></ul><h2 id="_5-thu-tu-build" tabindex="-1">5. Thứ tự build <a class="header-anchor" href="#_5-thu-tu-build" aria-label="Permalink to &quot;5. Thứ tự build&quot;">​</a></h2><ol><li>Context/model thêm field (<code>emotion_dists</code>, <code>RawComment</code>, <code>emotion_dist</code>).</li><li><code>phobert.predict_emotion_probs</code> + <code>label_posts</code> 5-tuple.</li><li>T2 lưu dist → T4 burst → T5 sentiment → T7 gộp + rank.</li><li>Wire step list <code>trend_service.py</code> / <code>run.py</code>.</li><li>Demo UI hiển thị breakdown; smoke test cập nhật 5-tuple.</li></ol><h2 id="_6-rui-ro" tabindex="-1">6. Rủi ro <a class="header-anchor" href="#_6-rui-ro" aria-label="Permalink to &quot;6. Rủi ro&quot;">​</a></h2><ul><li>Neutral áp đảo (emotion v12 classify comment ngắn → trung_lập) → mood thiếu phân biệt; chấp nhận v1, tune ngưỡng sau.</li><li>Production smoke test bị chặn bởi dep thiếu (<code>groq</code>/<code>torch</code>) — xác minh bằng <code>py_compile</code>; cần env đủ deps để chạy test thật.</li></ul>',19)])])}const u=t(a,[["render",c]]);export{m as __pageData,u as default};
